query.CommandText = "SELECT Title FROM Books WHERE BookId = @id;";
query.Parameters.AddWithValue("@id", 1);
using var reader = query.ExecuteReader();
while (reader.Read())
    Console.WriteLine(reader.GetString(0));
```

