long Factorial(int n)
{
 if(n<0||n>20)throw new ArgumentOutOfRangeException(nameof(n));
 Console.WriteLine($"call {n}");
 long result=n<=1?1:checked(n*Factorial(n-1));
 Console.WriteLine($"return {n}: {result}");return result;

